window.CDL_QUESTIONS_SET2 = [
  { id: "gk-61", category: "general", topic: "Mirrors", q: "Convex (curved) mirrors are useful because they:", choices: ["Make objects look larger and closer", "Show a wider view, though objects look smaller and farther away", "Eliminate all blind spots", "Replace the need to look ahead 12–15 seconds"], a: 1, why: "Convex mirrors widen the view but distort distance. Check a flat mirror before you change lanes." },
  { id: "gk-62", category: "general", topic: "Blind spots", q: "The areas around a commercial vehicle that other drivers disappear into are called:", choices: ["Escape ramps", "No-zones / blind spots", "Governor range", "Outage"], a: 1, why: "Large blind spots exist along both sides, immediately in front, and close behind. Assume a car there cannot see you well either." },
  { id: "gk-63", category: "general", topic: "Communicating", q: "You should signal a turn or lane change:", choices: ["After you start the move", "Early enough that others know your plan, then cancel the signal when the move is done", "Only at night", "Only if a car is beside you"], a: 1, why: "Signal before you slow, turn, or change lanes. Turn the signal off after you complete the move so you do not confuse others." },
  { id: "gk-64", category: "general", topic: "Horn", q: "Use the horn:", choices: ["To vent anger at a slow car", "When needed to warn others of your presence", "Instead of brakes", "Only in school zones"], a: 1, why: "The horn is a warning device, not a punishment. Tap it when someone may not see you." },
  { id: "gk-65", category: "general", topic: "Four-way flashers", q: "Four-way emergency flashers should be used:", choices: ["As a substitute for turn signals on every freeway merge", "When you are stopped on the road or traveling unusually slowly to warn others", "Only when backing", "To pass on the right"], a: 1, why: "Hazards warn others you are stopped, disabled, or moving very slowly. Still use triangles when required." },
  { id: "gk-66", category: "general", topic: "Night beams", q: "High beams should be dimmed:", choices: ["Never, on rural roads", "When you are within 500 feet of an oncoming vehicle, and when following closely enough that you could blind the driver ahead", "Only in fog", "Only inside city limits"], a: 1, why: "High beams help you see, but they can blind others. Dim for oncoming traffic and when you are behind someone." },
  { id: "gk-67", category: "general", topic: "Night driving", q: "If another driver does not dim their high beams, you should:", choices: ["Look to the right edge of the road and slow down if needed", "Look straight into the lights so you can judge distance", "Speed up to get past them", "Turn on your high beams to teach them a lesson"], a: 0, why: "Do not stare into glare. Use the right pavement edge as a guide and keep control of speed." },
  { id: "gk-68", category: "general", topic: "Speed", q: "Posted speed limits are:", choices: ["Always safe for a fully loaded combination in every condition", "The maximum under ideal conditions; you must go slower in traffic, weather, curves, or with a heavy load", "The minimum you must travel", "Only for cars"], a: 1, why: "A truck’s safe speed is often below the posted limit, especially on ramps, in rain, and when loaded high." },
  { id: "gk-69", category: "general", topic: "Speed", q: "If you double your speed, stopping distance is about:", choices: ["The same", "Twice as long", "Four times as long", "Half as long"], a: 2, why: "Kinetic energy and braking distance increase with the square of speed. Twice the speed is about four times the stopping distance." },
  { id: "gk-70", category: "general", topic: "Weight and stopping", q: "Extra weight generally:", choices: ["Always shortens stopping distance because tires grip more", "Increases stopping distance and makes brakes work harder", "Has no effect on brakes", "Lets you take curves faster"], a: 1, why: "Heavier vehicles take longer to stop and heat the brakes more on downgrades. Empty vehicles can lock wheels more easily." },
  { id: "gk-71", category: "general", topic: "Wet roads", q: "On a wet road you should:", choices: ["Reduce speed and increase following distance", "Drive at the dry-road speed because trucks cut through water", "Use cruise control to hold a steady pace", "Brake harder than usual so ABS works"], a: 0, why: "Water cuts traction. Slow down, especially in the first minutes of rain when oil films the surface." },
  { id: "gk-72", category: "general", topic: "Black ice", q: "Black ice is likely when:", choices: ["The temperature is near freezing and the road looks wet but you hear little tire spray", "The pavement is dry and 80°F", "It is snowing heavily and packed", "You are in a desert at noon"], a: 0, why: "Black ice is a thin, hard-to-see glaze. If the road looks wet and spray disappears in freezing weather, slow down immediately." },
  { id: "gk-73", category: "general", topic: "Hydroplane", q: "If you begin to hydroplane you should:", choices: ["Brake hard and steer sharply", "Ease off the accelerator and steer straight until the tires grip again", "Speed up to cut through the water", "Downshift to reverse"], a: 1, why: "Do not brake or jerk the wheel. Let the tires find the road again, then slow gradually." },
  { id: "gk-74", category: "general", topic: "Retarders", q: "Engine or driveline retarders:", choices: ["Should be used on ice and packed snow for extra stopping power", "Can cause drive-wheel skids on slippery roads and should be turned off when traction is poor", "Replace service brakes on every trip", "Work only on trailers"], a: 1, why: "Retarders help on dry downgrades but can lock or spin drive wheels on slick pavement. Switch them off when it is slippery." },
  { id: "gk-75", category: "general", topic: "Right turn", q: "The proper way to make a right turn in a long vehicle is to:", choices: ["Swing left first so cars can sneak by on the right", "Keep the rear of the vehicle close to the curb and turn wide as you complete the turn, without starting in the left lane", "Turn from the left lane", "Cut the corner over the sidewalk"], a: 1, why: "If you swing left at the start, a driver may try to pass on the right. Stay right, then swing as needed to finish the turn." },
  { id: "gk-76", category: "general", topic: "Passing", q: "Before you pass you must:", choices: ["Assume the other driver will slow down", "Check ahead, behind, and to the sides, signal, and be sure you have space and speed to complete the pass safely", "Pass on the shoulder", "Pass on a hill without sight distance"], a: 1, why: "Trucks accelerate slowly. Do not pass unless you can get back over without forcing someone to brake." },
  { id: "gk-77", category: "general", topic: "Being passed", q: "When being passed you should:", choices: ["Speed up to show the other driver", "Stay to the right and maintain speed, or ease off slightly so they can finish", "Brake hard", "Move left"], a: 1, why: "Help the passer complete the pass. Speeding up or wandering left is how sideswipes happen." },
  { id: "gk-78", category: "general", topic: "Space beside", q: "You need extra space to the sides because:", choices: ["Commercial vehicles wander more in wind and on crowned roads, and they off-track", "Mirrors eliminate all side risk", "Lanes are wider for trucks than for cars", "ABS steers for you"], a: 0, why: "Keep space on both sides. Avoid driving beside others for long stretches." },
  { id: "gk-79", category: "general", topic: "Space behind", q: "The best way to deal with a tailgater is to:", choices: ["Brake-check them", "Avoid quick speed changes, increase space ahead, and change lanes when it is safe if they can pass", "Block them from passing", "Flash high beams continuously"], a: 1, why: "You cannot control a tailgater. Give yourself room to stop smoothly so they are less likely to hit you." },
  { id: "gk-80", category: "general", topic: "Hazards", q: "A hazard is:", choices: ["Only a vehicle already in your lane", "Any road condition or road user that could become a danger", "Only weather", "Only other trucks"], a: 1, why: "Hazard perception means spotting things that might go wrong: kids, shops, on-ramps, brake lights, ice, work zones." },
  { id: "gk-81", category: "general", topic: "Distracted driving", q: "Which is a distracted-driving risk in a CMV?", choices: ["Phones, dispatch devices, eating, and map work while the vehicle is moving", "Checking mirrors", "Signaling", "Scanning 12–15 seconds ahead"], a: 0, why: "Anything that takes eyes, hands, or mind off driving is a distraction. Pull over to handle devices and paperwork." },
  { id: "gk-82", category: "general", topic: "Drugs", q: "Prescription and over-the-counter drugs:", choices: ["Are always legal to use while driving a CMV", "Can be disqualifying if they affect driving; you must know the effects and your employer/medical rules", "Only matter if they are illegal street drugs", "Are safer than coffee"], a: 1, why: "Many legal drugs cause drowsiness. Some are banned for CMV drivers. Ask a medical examiner if unsure." },
  { id: "gk-83", category: "general", topic: "Alcohol limit", q: "The CMV blood-alcohol limit that is a CDL alcohol violation is:", choices: ["0.08, same as a car", "0.04 or more, and any detectable alcohol still means 24 hours out of service", "0.10", "0.00 only if you are under 21"], a: 1, why: "CDL standard is 0.04. Any measurable alcohol while operating a CMV is 24-hour out of service even below 0.04." },
  { id: "gk-84", category: "general", topic: "Disqualification", q: "You can lose your CDL for one year (first offense, non-HazMat) for:", choices: ["A parking ticket", "Major offenses such as DUI in a CMV, leaving the scene, or using a CMV in a felony", "A single 5-mph speeding ticket", "Forgetting a log for one day"], a: 1, why: "Major offenses trigger CDL disqualification. HazMat while committing the offense can make the first ban 3 years. A second major can be for life." },
  { id: "gk-85", category: "general", topic: "Railroad CMV", q: "A commercial vehicle hauling cargo (not a required-stop bus or placarded load) should:", choices: ["Never slow for tracks", "Slow down, look and listen, never shift on the tracks, and never stop on the tracks", "Stop on every crossing including exempt industrial tracks inside a yard with no rails in use", "Race across to beat a train"], a: 1, why: "Trucks can hang up on humped crossings. Know your clearance on the other side before you start across." },
  { id: "gk-86", category: "general", topic: "Crash", q: "If you are in a crash, your first responsibilities are to:", choices: ["Move the injured even if it could worsen injuries", "Protect the scene, get help, and assist the injured without causing further harm", "Leave to call from home", "Argue fault first"], a: 1, why: "Prevent another crash, notify authorities, give aid you are trained to give. Do not move the seriously injured unless there is fire or another immediate danger." },
  { id: "gk-87", category: "general", topic: "Fire types", q: "A Class B fire involves:", choices: ["Wood and paper", "Flammable liquids such as fuel or grease", "Energized electrical equipment only", "Cooking oil in a deep fryer only as Class K"], a: 1, why: "Class A = ordinary combustibles. Class B = flammable liquids. Class C = electrical. Use the right extinguisher." },
  { id: "gk-88", category: "general", topic: "Engine fire", q: "If you have an engine fire, you should:", choices: ["Throw the hood open immediately and stand in the smoke", "Use the extinguisher through louvers or from a safe angle; opening the hood can feed the fire with air", "Pour water on burning fuel under the engine", "Keep driving to blow it out"], a: 1, why: "A sudden rush of air can make the fire worse. Shoot through vents if you can, from upwind." },
  { id: "gk-89", category: "general", topic: "Cargo fire", q: "If you suspect a cargo fire in a closed trailer, you should:", choices: ["Open the doors right away to look", "Keep the doors shut if you cannot put the fire out, get people away, and call the fire department", "Drive faster for airflow", "Park in a tunnel"], a: 1, why: "Opening doors can feed oxygen to the fire. Closed doors may starve it until firefighters arrive." },
  { id: "gk-90", category: "general", topic: "Triangles two-lane", q: "Stopped on a two-way undivided road, warning devices generally go:", choices: ["Only behind the truck", "Within 10 feet of the vehicle and about 100 feet toward traffic in both directions", "500 feet in one direction only", "Inside the cab"], a: 1, why: "Mark the vehicle and give approaching drivers time from both ways. On hills/curves, place the far triangle where it can be seen—up to 500 feet." },
  { id: "gk-91", category: "general", topic: "Escape path", q: "If brakes fail on a grade and there is no escape ramp, you should:", choices: ["Stay in gear if you can, look for an escape path, and not jump unless it is a last resort", "Shift to neutral immediately", "Shut the engine off while still in high gear always", "Open the door and stand on the running board"], a: 0, why: "Look for an open escape: off-road upgrade, open field. Jumping is extremely dangerous." },
  { id: "gk-92", category: "general", topic: "Stuck accelerator", q: "If the accelerator sticks, you should:", choices: ["Reach down and pull the pedal while steering with one finger", "Steer, shift to neutral or depress the clutch, brake, and get off the road", "Turn off the key immediately on a power-steering vehicle without a plan", "Speed up to unstick it"], a: 1, why: "Get the vehicle out of gear so engine speed does not drive you, then brake and stop safely. Know how your key/steering lock works before you shut the engine off." },
  { id: "gk-93", category: "general", topic: "Steering failure", q: "If you lose steering, you should:", choices: ["Keep a firm grip, stop as quickly and safely as you can, and not brake so hard that you skid if you still have some control", "Accelerate", "Jump out immediately at highway speed", "Use only the trailer hand valve at 60 mph"], a: 0, why: "Stop in a straight line if you can. Hard lockup can make a bad situation worse if any steerability remains." },
  { id: "gk-94", category: "general", topic: "Skid types", q: "Drive-wheel acceleration skids are caused by:", choices: ["Too much power for conditions, so drive tires spin", "Only trailer brakes", "Too little air pressure in the tanks", "Looking 12–15 seconds ahead"], a: 0, why: "On ice, snow, or a light drive axle, excess throttle spins the tires. Ease off the accelerator." },
  { id: "gk-95", category: "general", topic: "Countersteer", q: "Countersteering means:", choices: ["Turning the wheel back the other way as soon as a skid or swerve is corrected so you do not overcorrect", "Never steering in a skid", "Steering only with the trailer", "Locking the wheel at full left"], a: 0, why: "You steer into the skid to regain roll, then you must countersteer or the vehicle will skid the other way." },
  { id: "gk-96", category: "general", topic: "Shifting", q: "If you cannot get the vehicle into the right gear on a grade, you should:", choices: ["Keep looking at the shift lever until you find it", "Get the vehicle back under control first; do not stare at the shifter", "Coast in neutral down a long hill", "Rev to redline in any gear"], a: 1, why: "Eyes belong on the road. Neutral-coasting on a grade is dangerous because you lose engine braking and may not get a gear back." },
  { id: "gk-97", category: "general", topic: "Double clutching", q: "Double clutching is used to:", choices: ["Match engine and transmission speed so gears engage without grinding", "Apply both parking brakes", "Warm dual tires", "Test ABS"], a: 0, why: "Release clutch, shift to neutral, match RPM, clutch again into the next gear. Grinding means the RPM is wrong." },
  { id: "gk-98", category: "general", topic: "Winterfront", q: "A winterfront or radiator shutters closed too tightly can:", choices: ["Make the engine overheat and stop", "Improve braking", "Charge air tanks faster", "Prevent carbon monoxide"], a: 0, why: "The engine needs airflow. Ice-stuck shutters or an over-closed winterfront can overheat the engine." },
  { id: "gk-99", category: "general", topic: "Exhaust winter", q: "In winter, exhaust leaks are extra dangerous because:", choices: ["Windows are often closed, so carbon monoxide can collect in the cab", "They heat the trailer", "They defrost the windshield better", "They dry the air tanks"], a: 0, why: "CO is poisonous and odorless in many cases. Inspect the exhaust when the cab is sealed up." },
  { id: "gk-100", category: "general", topic: "Tire chains", q: "When chains are required, you should:", choices: ["Carry the right size, know how to put them on, and chain up before you cannot climb or stop", "Wait until you are already stuck on the summit", "Chain only the trailer lift axle", "Drive 70 mph with chains"], a: 0, why: "Chain laws in mountain passes are serious. Practice chaining in a lot, not on a dark grade." },
  { id: "gk-101", category: "general", topic: "Hot weather", q: "In very hot weather, watch for:", choices: ["Tire blowouts, engine overheating, and brake fade on grades", "Black ice only", "Better traction than in rain", "No need to inspect tires"], a: 0, why: "Heat builds tire pressure and brake temperature. Check tires when stopped; do not bleed hot tires down to the cold pressure." },
  { id: "gk-102", category: "general", topic: "Hot tires", q: "If a tire is hot when you stop, you should:", choices: ["Bleed air out immediately to the cold-inflation number", "Stay off it until it cools and then check pressure; bleeding a hot tire can cause failure when it cools", "Pour water on a recap while driving", "Keep running at highway speed to cool it"], a: 1, why: "Pressure rises with heat. If you deflate a hot tire to the cold spec, it will be underinflated when it cools." },
  { id: "gk-103", category: "general", topic: "Work zones", q: "In a construction zone you should:", choices: ["Maintain highway speed to clear the zone faster", "Slow down, increase space, and watch for workers, sudden lane shifts, and uneven pavement", "Use only the left shoulder", "Assume cones are optional"], a: 1, why: "Fines and crash risk are higher. Expect the unexpected." },
  { id: "gk-104", category: "general", topic: "Pedestrians", q: "At intersections, commercial drivers should:", choices: ["Assume pedestrians and bikes will wait", "Scan extra carefully because the cab sits high and the vehicle needs more time and space to stop", "Honk and proceed without looking right", "Block the crosswalk so cars cannot sneak by"], a: 1, why: "You cannot see as well close-in. Right turns especially hide pedestrians." },
  { id: "gk-105", category: "general", topic: "CA height", q: "The general maximum vehicle height in California is:", choices: ["12 feet", "13 feet 6 inches in every state including CA", "14 feet, unless a lower limit is posted", "16 feet on all highways"], a: 2, why: "California generally allows 14 feet. Posted overpasses can be lower. Know your actual loaded height." },
  { id: "gk-106", category: "general", topic: "CA width", q: "The general maximum vehicle width in California is about:", choices: ["96 inches on every road with no exceptions", "102 inches (8½ feet), with local roads sometimes posted narrower", "120 inches for all trucks", "8 feet including mirrors"], a: 1, why: "102 inches is the common CA/federal width. Mirrors and required devices may extend. Some local roads are 96 inches." },
  { id: "gk-107", category: "general", topic: "GVWR", q: "GVWR means:", choices: ["The actual weight of the vehicle right now", "The manufacturer’s maximum loaded weight rating for that vehicle", "Cargo weight only", "The trailer kingpin rating"], a: 1, why: "GVWR is a rating. GVW is actual weight. You can be illegal if actual weight exceeds ratings or axle/bridge limits even if you are under a rating on paper." },
  { id: "gk-108", category: "general", topic: "HOS interstate", q: "After 10 consecutive hours off duty, an interstate property-carrying driver generally may drive:", choices: ["Unlimited hours", "11 hours, not beyond the 14th hour after coming on duty", "16 hours of driving", "24 hours if coffee is used"], a: 1, why: "Federal 11-hour driving limit inside a 14-hour window, with other limits (30-minute break, 60/70 hour) also applying." },
  { id: "gk-109", category: "general", topic: "HOS CA intra", q: "California intrastate property-carrying hours of service generally allow:", choices: ["The same 11/14 as interstate with no differences", "Up to 12 hours driving and 16 hours on duty, then 10 hours off (with sleeper exceptions)", "No off-duty requirement", "Only 8 hours driving"], a: 1, why: "Intrastate CA rules differ from interstate. Confirm current CHP/FMCSA charts before you log." },
  { id: "gk-110", category: "general", topic: "Log", q: "A record of duty status is required so that:", choices: ["Dispatch can ignore HOS", "Officers can verify you are within hours-of-service limits", "You can skip vehicle inspections", "Fuel tax is optional"], a: 1, why: "Paper logs or ELDs document on-duty, driving, sleeper, and off-duty time." },
  { id: "gk-111", category: "general", topic: "Medical", q: "To keep a CDL valid for interstate CMV operation you generally must have:", choices: ["No medical qualification", "A current medical examiner’s certificate (DOT physical) as required", "Only a vision screening at AAA", "A dentist’s note"], a: 1, why: "CDL and medical certification go together. Expired medical can downgrade the license." },
  { id: "gk-112", category: "general", topic: "CLP wait", q: "Before taking the California CDL skills test you must hold a CLP for at least:", choices: ["24 hours", "14 days", "90 days", "1 year"], a: 1, why: "Federal/CA rule: at least 14 days with the learner’s permit before the skills test." },
  { id: "gk-113", category: "general", topic: "ELDT", q: "First-time Class A applicants must generally complete:", choices: ["No training if they read a handbook", "Entry-Level Driver Training (ELDT) with a registered provider before the skills test", "Only YouTube videos", "Only the written tests"], a: 1, why: "ELDT theory and behind-the-wheel training are required for most new Class A (and passenger/school bus/HazMat in their cases)." },
  { id: "gk-114", category: "general", topic: "Perception", q: "Perception distance is the distance traveled while you:", choices: ["The brakes are applied", "See, identify, and understand a hazard", "Wait for air to fill the chambers", "Fill out a log"], a: 1, why: "You cannot start reacting until you perceive the hazard. Looking ahead shortens this." },
  { id: "gk-115", category: "general", topic: "Reaction", q: "Reaction distance is the distance traveled while you:", choices: ["Move your foot to the brake after you decide to stop", "Wait for the trailer to couple", "Look at a GPS only", "The vehicle is already stopped"], a: 0, why: "Even a second of reaction at highway speed is many feet." },
  { id: "gk-116", category: "general", topic: "Covered loads", q: "In California, loads of garbage, trash, or similar debris:", choices: ["May blow freely if you are late", "Must be covered so material cannot spill onto the highway", "Are exempt from CVC load rules", "Only need covering at night"], a: 1, why: "CVC requires covering such loads. Aggregate has its own 6-inch-below-the-rail and flap rules." },
  { id: "gk-117", category: "general", topic: "Livestock", q: "When hauling livestock that does not fill the trailer, you should:", choices: ["Let animals run the full length so they get exercise", "Use false bulkheads or similar to keep them bunched; they can lean on curves and raise rollover risk", "Load all weight on the roof", "Never inspect the trailer"], a: 1, why: "Moving animals change the center of gravity. Bunch them and take curves even slower." },
  { id: "gk-118", category: "general", topic: "Oversize", q: "If your load is over legal height, width, or length you generally need:", choices: ["Nothing if you drive at night", "Proper permits, flags/lights/escorts as required, and a route that will clear", "Only a Class C license", "To split the load after you are already on the freeway"], a: 1, why: "Oversize moves are regulated. Guessing on a low bridge is how loads get peeled off." },
  { id: "gk-119", category: "general", topic: "Wind", q: "Strong winds are most dangerous when:", choices: ["You are heavy and in a valley", "You are empty or have a high-profile trailer on a bridge or open grade, or when passing or being passed by another truck", "ABS is on", "It is 70°F and calm"], a: 1, why: "Wind can shove a light trailer. Slow down; both hands on the wheel; be ready for a blast when you come out from behind another vehicle." },
  { id: "gk-120", category: "general", topic: "Backing helper", q: "When you have a helper while backing:", choices: ["You are not responsible if they are hit", "Agree on hand signals, keep them in sight, and stop immediately if you lose sight of them", "Have them stand behind the trailer in the blind spot the whole time", "Rely only on the horn"], a: 1, why: "If you cannot see the helper, stop. Helpers have been crushed in backing crashes." },

  { id: "ab-46", category: "airBrakes", topic: "Compressor drive", q: "Air compressors are usually driven by:", choices: ["The transmission output only", "The engine, by gears, a belt, or a shaft", "The trailer ABS lamp", "The steering pump exclusively"], a: 1, why: "If the engine is not running, the compressor is not building air (engine-off leakage tests use stored air)." },
  { id: "ab-47", category: "airBrakes", topic: "Cut-out identify", q: "During the skills test you must be able to identify governor cut-out by:", choices: ["Guessing 80 psi", "Watching the gauges until pressure stops rising in the normal 120–140 psi area (or the manufacturer’s spec) and saying that value", "Waiting for spring brakes", "Reading the speedometer"], a: 1, why: "Examiners want the actual cut-out you observed, compared with the allowed range." },
  { id: "ab-48", category: "airBrakes", topic: "Manual drain", q: "On tanks with manual petcocks, drain:", choices: ["Only the wet tank; others never collect water", "All tanks, because moisture can collect in more than one reservoir", "Only in summer", "By removing the safety valve"], a: 1, why: "The first (supply/wet) tank gets the most water, but other tanks still need draining unless they have working automatic drains." },
  { id: "ab-49", category: "airBrakes", topic: "Automatic drain", q: "If a tank has an automatic drain, you should still:", choices: ["Never look at it", "Check that it is working and that the tank is not full of sludge", "Weld it shut", "Replace it with a rag"], a: 1, why: "Automatic drains fail. Part of a pre-trip is confirming they actually expel moisture." },
  { id: "ab-50", category: "airBrakes", topic: "Relay valve", q: "A relay valve on a trailer or rear axle is used to:", choices: ["Steer the vehicle", "Speed brake application and release by using local tank air when it gets a signal from the service line", "Charge the batteries", "Lock the fifth wheel"], a: 1, why: "Long lines would be slow without relays. The signal line tells a nearby reservoir to apply the brakes." },
  { id: "ab-51", category: "airBrakes", topic: "Quick release", q: "Quick-release valves help:", choices: ["Build air faster from 50 psi", "Exhaust air quickly from chambers when you let off the pedal so brakes release fast", "Apply parking brakes", "Dim headlights"], a: 1, why: "Fast release keeps brakes from dragging." },
  { id: "ab-52", category: "airBrakes", topic: "Service vs parking", q: "Service brakes are applied by ____; parking/emergency spring brakes by ____.", choices: ["Air pressure when you push the pedal; springs when air is released", "Springs; air only", "The horn; the 4-ways", "ABS; the kingpin"], a: 0, why: "Remember: air applies service brakes. Loss of air applies springs." },
  { id: "ab-53", category: "airBrakes", topic: "Emergency brakes", q: "On air-brake vehicles, emergency braking capability is usually provided by:", choices: ["The horn", "Spring brakes and/or a separate emergency system that applies if air is lost", "The clutch only", "Engine oil pressure"], a: 1, why: "Parking and emergency are spring-held because air can leak away." },
  { id: "ab-54", category: "airBrakes", topic: "Low air one circuit", q: "In a dual system, if the warning comes on, you may still have:", choices: ["No brakes at all in every case", "Partial braking from the other circuit, but stopping distance will be longer—stop now", "Better brakes than before", "Unlimited driving time"], a: 1, why: "That is why dual systems exist. You still stop immediately because you have already lost a lot of reserve." },
  { id: "ab-55", category: "airBrakes", topic: "Bus warning", q: "On many large buses, low-air warning devices may activate at:", choices: ["20 psi only", "80–85 psi, higher than the 55–75 psi truck range", "150 psi", "Cut-out pressure"], a: 1, why: "If you test in a bus, tell the examiner your vehicle is designed to warn higher than 55 psi." },
  { id: "ab-56", category: "airBrakes", topic: "Triple reservoir bus", q: "If a bus parking-brake valve does not pop out around 20 psi because of an isolated parking tank, you must:", choices: ["Skip the spring-brake test", "Show that spring brakes have applied, often by trying to pull forward gently and feeling them drag", "Drain all tanks and leave", "Use stab braking"], a: 1, why: "Handbook describes a special demonstration for those buses. Do not use that pull-forward method on combination vehicles as the normal test." },
  { id: "ab-57", category: "airBrakes", topic: "Chocks leak test", q: "Why chock wheels for air-leak tests?", back: "So the vehicle cannot roll when parking brakes are released for the test.", choices: ["So the vehicle cannot roll when you release parking brakes to perform the test", "To increase leak rate", "To disable ABS", "To drain fuel"], a: 0, why: "The applied leak test requires parking brakes released. Chocks replace that holding force." },
  { id: "ab-58", category: "airBrakes", topic: "Stabilize gauge", q: "On the applied leak test, start timing only after:", choices: ["You start the engine again", "The air gauge needle has settled from the initial apply", "You hit 20 psi", "ABS cycles"], a: 1, why: "The first moment of apply can show a drop as chambers fill. Time 1 minute after it stabilizes." },
  { id: "ab-59", category: "airBrakes", topic: "Listen leaks", q: "Besides watching the gauge on a leak test, you should:", choices: ["Listen for hissing leaks", "Rev the engine to mask noise", "Turn the radio up", "Open all petcocks"], a: 0, why: "A gauge might still be in limits while a hose hisses. Find and fix leaks." },
  { id: "ab-60", category: "airBrakes", topic: "Too much leak", q: "If applied leakage exceeds the limit you must:", choices: ["Drive slower to the shop on the freeway", "Not operate the vehicle until it is repaired", "Add air with a tire inflator", "Pull the yellow knob and ignore it"], a: 1, why: "Excess leak means a defect. It is an inspection failure and a real-world no-go." },
  { id: "ab-61", category: "airBrakes", topic: "Pushrod stroke", q: "Long pushrod stroke means:", choices: ["Brakes are extra powerful", "Brakes may be out of adjustment or mechanically worn, so stopping power is reduced", "ABS is working", "Cut-out is high"], a: 1, why: "Stroke beyond the limit is the roadside adjustment check. Know your chamber type’s maximum stroke." },
  { id: "ab-62", category: "airBrakes", topic: "Oil-soaked linings", q: "Oil or grease on brake linings:", choices: ["Improves friction", "Is a defect; linings can fail to hold", "Is required on S-cams", "Only matters on cars"], a: 1, why: "Contaminated linings do not grip. Find the leak (hub, chamber, axle seal)." },
  { id: "ab-63", category: "airBrakes", topic: "Drums hot", q: "If brake drums are too hot to touch after a trip, it can indicate:", choices: ["Proper adjustment always", "Dragging brakes, overuse on a grade, or a vehicle problem that needs checking", "The parking brake was not used", "Low engine oil only"], a: 1, why: "Heat is energy from stopping. Abnormal heat means something is wrong or the driver used brakes as the only downhill control." },
  { id: "ab-64", category: "airBrakes", topic: "ABS trailer lamp", q: "A yellow ABS lamp on the left rear of a trailer that stays on means:", choices: ["Trailer ABS may not be working", "The trailer has no brakes at all", "You must disconnect the 7-way", "Cut-in is 55 psi"], a: 0, why: "Trailer ABS fault. You still have brakes. Get it serviced." },
  { id: "ab-65", deck: "air-brakes", category: "airBrakes", topic: "No ABS pump", q: "Pumping the pedal on a working ABS vehicle in a panic stop:", choices: ["Helps ABS", "Can defeat ABS; keep firm pressure instead", "Charges tanks", "Releases spring brakes"], a: 1, why: "ABS already pulses faster than your foot. Pumping can confuse the system." },
  { id: "ab-66", category: "airBrakes", topic: "Power skid", q: "ABS will not prevent a skid caused by:", choices: ["Over-braking on a slippery road", "Spinning the drive wheels or going too fast in a turn", "Service-brake lockup it was designed to catch", "A single locked wheel it can still modulate"], a: 1, why: "ABS is anti-lock braking, not anti-stupid. Speed and throttle still cause skids." },
  { id: "ab-67", category: "airBrakes", topic: "Air over hydraulic", q: "Air-over-hydraulic brakes:", choices: ["Do not require the air-brake knowledge test", "Still use air and require the air-brake test; failure means an air-brake restriction", "Are the same as electric trailer brakes on a pickup", "Have no tanks"], a: 1, why: "If the vehicle uses air in the brake system, you take the air-brake test or get a restriction." },
  { id: "ab-68", category: "airBrakes", topic: "L restriction", q: "If you do not pass the air-brake knowledge and skills portions, your CDL can carry:", choices: ["An H endorsement", "An L restriction: no air-brake vehicles", "A T endorsement", "No medical card"], a: 1, why: "L = air brakes not allowed. Most Class A jobs require air brakes, so you need to pass this test." },
  { id: "ab-69", category: "airBrakes", topic: "Hand valve combo", q: "Using only the trailer hand valve for a highway stop can:", choices: ["Be the safest stop", "Lock trailer wheels and jackknife the combination", "Charge the tractor tanks", "Replace ABS"], a: 1, why: "The foot valve applies tractor and trailer together in balance. Trailer-only braking is for tests, rollback, or light checks—not panic highway stops." },
  { id: "ab-70", category: "airBrakes", topic: "Balance", q: "If tractor brakes are much stronger than trailer brakes:", choices: ["The combination stops shorter with no risk", "The tractor can be shoved sideways or jackknife under hard braking", "The trailer always locks first", "Off-tracking disappears"], a: 1, why: "Brake balance matters. Poor trailer brakes or aggressive tractor braking causes tractor jackknife." },
  { id: "ab-71", category: "airBrakes", topic: "Ice empty", q: "On ice, an empty rig should be braked:", choices: ["Harder than when loaded because it is lighter", "Very gently; light axles lock easily", "With parking brakes at 50 mph", "Only with the hand valve fully applied"], a: 1, why: "Less weight = less traction. Empty + ice + hard pedal is a jackknife setup." },
  { id: "ab-72", category: "airBrakes", topic: "Safety valve blows", q: "If the 150 psi safety valve is releasing air:", choices: ["That is normal cut-out", "The governor or another part has failed; do not keep driving that way", "You need more alcohol in the evaporator", "ABS is on"], a: 1, why: "The safety valve is a last-resort overpressure device. Something is wrong upstream." },
  { id: "ab-73", category: "airBrakes", topic: "Build slow", q: "If air pressure builds much slower than the handbook times, you should:", choices: ["Go anyway if you have 60 psi", "Find the leak, belt problem, or compressor issue before driving", "Fan the pedal to help the compressor", "Pull the red knob and drive"], a: 1, why: "Slow buildup means the compressor cannot keep up. You will run out of air in traffic or on a grade." },
  { id: "ab-74", category: "airBrakes", topic: "Idle rpm", q: "Air-build tests are done at:", choices: ["Maximum RPM in every case", "Normal idle, often about 600–900 rpm as specified", "Engine off", "Stall speed"], a: 1, why: "Verbalize idle RPM and the 85–100 in 45 seconds standard for dual systems." },
  { id: "ab-75", category: "airBrakes", topic: "Foundation heat", q: "Brake drums that are cracked, missing pieces, or showing signs of extreme heat should be:", choices: ["Painted and used", "Taken out of service until repaired", "Filled with water", "Used only at night"], a: 1, why: "Damaged drums can fail suddenly. Heat checking and severe cracks are inspection items." },

  { id: "cv-41", category: "combination", topic: "Rollover stats", q: "More than half of tractor-trailer rollovers are linked to:", choices: ["Too much speed in a curve or on a ramp", "Too much fifth-wheel grease", "Using convex mirrors", "Looking 12–15 seconds ahead"], a: 0, why: "Slow before the curve. Posted ramp speeds are often for cars." },
  { id: "cv-42", category: "combination", topic: "Trailer swing", q: "A quick lane change in a combination can cause the trailer to:", choices: ["Stay perfectly in line always", "Swing out farther than the tractor (rearward amplification)", "Lose the kingpin grease only", "Charge the air tanks"], a: 1, why: "The rear of the trailer can off-track or whip. Change lanes smoothly and one at a time." },
  { id: "cv-43", category: "combination", topic: "Avoid backing", q: "Backing a tractor-trailer is risky because:", choices: ["You cannot see directly behind and the trailer turns opposite the wheel at first", "Trailers cannot turn", "ABS forbids backing", "Landing gear must be down"], a: 0, why: "Get out and look (GOAL). Use a helper. Plan so you pull through instead of backing." },
  { id: "cv-44", category: "combination", topic: "Pull-ups", q: "When backing, pull-ups are:", choices: ["A failure on every test", "Allowed and often the safest way to reposition before the trailer goes too far off path", "Only for buses", "Done at 20 mph"], a: 1, why: "On the CDL basic-control test, pull-ups may cost points but hitting a boundary costs more. In real yards, pull up rather than hit a dock or car." },
  { id: "cv-45", category: "combination", topic: "Sight-side", q: "Sight-side backing (toward the driver’s side) is usually:", choices: ["Harder than blind-side backing", "Easier than blind-side backing because you can see more of the trailer’s path", "Illegal", "Done without mirrors"], a: 1, why: "Back to the left when you can. Blind-side (right) backing needs extra caution and a spotter." },
  { id: "cv-46", category: "combination", topic: "Trailer drift", q: "If the trailer starts to drift off the backing path, correct:", choices: ["After it is far off, with a huge steer", "Immediately with a small steer toward the drift, before the error grows", "By accelerating", "By applying only trailer brakes hard"], a: 1, why: "Small early corrections beat big late ones that jack the trailer over." },
  { id: "cv-47", category: "combination", topic: "Couple sequence", q: "After the fifth wheel touches the trailer, next you should:", choices: ["Shoot under at speed", "Check kingpin alignment, chock/trailer brakes as required, then back slowly until locked", "Raise landing gear all the way before locking", "Disconnect the 7-way"], a: 1, why: "Confirm height and line-up, then lock. Raising gear fully before a solid couple can drop the trailer if the lock fails." },
  { id: "cv-48", category: "combination", topic: "Slight raise gear", q: "After you think you are locked, raise landing gear slightly, then tug-test, because:", choices: ["It looks neat", "A slight raise lets you see if the trailer is really on the tractor before you commit, and a tug checks the lock", "It charges ABS", "It fills the tanks"], a: 1, why: "If the couple is false, you do not want the trailer standing only on half-raised gear. Know your training program’s exact order; the handbook’s steps include lock, visual, tug, then full raise." },
  { id: "cv-49", category: "combination", topic: "False couple", q: "A false couple is when:", choices: ["The kingpin sits on closed jaws or is not in the lock, so the trailer can drop when you pull", "Glad hands are red-to-red", "The fifth wheel is greased", "Landing gear is up"], a: 0, why: "Visual check + tug test exist to catch this before you pull into traffic." },
  { id: "cv-50", category: "combination", topic: "Unlocking handle", q: "Before coupling, the fifth-wheel release handle should be:", choices: ["In the locked/automatic-lock position with jaws open, ready to catch the kingpin", "Wired open for the whole trip", "Missing", "In your pocket"], a: 0, why: "If the handle is not set to lock, you can back under and never latch." },
  { id: "cv-51", category: "combination", topic: "Trailer brakes before couple", q: "Trailer parking/emergency brakes (or chocks) before coupling:", choices: ["Should hold the trailer so it does not roll when you back under", "Must be released so the trailer can roll away", "Are optional on a grade", "Replace lining inspection"], a: 0, why: "A rolling trailer during coupling is how people get hurt and equipment gets wrecked." },
  { id: "cv-52", category: "combination", topic: "Supply then electric", q: "A common safe order after mechanical couple is:", choices: ["Drive away, then hook air", "Connect air and electric, supply air to the trailer, wait for air, release trailer brakes, test trailer brakes, then raise gear fully and recheck couple/clearance", "Raise gear, then hope the jaws catch", "Pull the yellow knob and leave"], a: 1, why: "Charge the trailer, confirm brakes work, finish landing gear, walk around again. Exact school checklists vary slightly; do not skip air, electric, tests, or visual lock." },
  { id: "cv-53", category: "combination", topic: "Emergency line leak", q: "A major leak in the emergency (supply) line will:", choices: ["Do nothing", "Cause the tractor protection valve to close and trailer emergency/spring brakes to apply", "Only dim the ABS lamp", "Increase cut-out to 150"], a: 1, why: "That is how the trailer is supposed to stop if it breaks away." },
  { id: "cv-54", category: "combination", topic: "Service line leak", q: "A leak in the service (control) line can:", choices: ["Apply trailer brakes harder always", "Reduce or delay trailer service braking when you use the foot pedal", "Lock the fifth wheel", "Fill the coolant"], a: 1, why: "Service line carries the apply signal. A leak means weak or no trailer service brakes." },
  { id: "cv-55", category: "combination", topic: "Trailer tank", q: "Trailer air tanks:", choices: ["Are optional decorations", "Store air so trailer brakes can apply through relay valves; they must still drain moisture", "Replace tractor tanks", "Are filled with hydraulic fluid"], a: 1, why: "Inspect tank mounts, drains, and hoses on the trailer walk-around." },
  { id: "cv-56", category: "combination", topic: "Converter no springs", q: "Older trailers and many dollies without spring brakes:", choices: ["Cannot be towed", "Rely on air in the trailer tank for emergency brakes; if that air is gone, wheels may roll freely", "Always have perfect parking brakes", "Do not need chocks"], a: 1, why: "This is why crossed lines on old equipment is deadly, and why you chock and test brakes." },
  { id: "cv-57", category: "combination", topic: "Turn wide left", q: "If you start a left turn too soon in a combination:", choices: ["Nothing happens", "The left side of the trailer can off-track into another vehicle or the curb", "The kingpin unlocks", "ABS turns off"], a: 1, why: "Get the tractor out into the intersection so the trailer’s shorter path stays in your lane space." },
  { id: "cv-58", category: "combination", topic: "Tail swing", q: "On a tight turn, the rear of a long trailer or tractor can:", choices: ["Swing out and hit something on the outside of the turn", "Never swing", "Only swing if empty", "Swing only in reverse"], a: 0, why: "Front of tractor and rear overhang can both hit. Watch the off-track inside and the swing outside." },
  { id: "cv-59", category: "combination", topic: "Following combo", q: "A good extra reason combinations need more following distance is:", choices: ["Brake lag plus trailer weight, and the crash if you rear-end a car is severe", "They stop faster than cars", "Off-tracking shortens stops", "ABS removes following rules"], a: 0, why: "You will not win an argument with physics. Leave space." },
  { id: "cv-60", category: "combination", topic: "Bobtail", q: "A bobtail tractor (no trailer) can be:", choices: ["Always more stable than a loaded combination", "Harder to stop and easier to lock the drive wheels because there is little weight on the drive axles", "Unable to use spring brakes", "Exempt from air-brake tests"], a: 1, why: "Bobtails have less traction on the drive tires. Brake gently on slick roads." },
  { id: "cv-61", category: "combination", topic: "Weight transfer", q: "A sliding fifth wheel is moved to:", choices: ["Change weight on the tractor axles and to adjust turn clearance", "Change engine horsepower", "Drain air tanks", "Disable ABS"], a: 0, why: "Slide back to put more weight on the trailer axles / unload the tractor drive; slide forward to load the tractor more. Then lock the pins." },
  { id: "cv-62", category: "combination", topic: "Pin lock", q: "After you slide a fifth wheel you must:", choices: ["Leave pins out so it can move in turns", "Visually and physically confirm locking pins are fully engaged", "Grease the glad hands only", "Pull the red knob"], a: 1, why: "An unlocked slide can dump the trailer into the cab or off the back." },
  { id: "cv-63", category: "combination", topic: "Uncouple air first", q: "Before you pull the fifth-wheel release to uncouple, air lines should be:", choices: ["Still connected so the trailer has no brakes", "Disconnected and protected, with trailer secured by parking/emergency brakes and landing gear", "Tied to the bumper", "Open to the atmosphere while you drive away"], a: 1, why: "Do not tear the lines out by driving away coupled to hoses. Secure the trailer first." },
  { id: "cv-64", category: "combination", topic: "Soft ground", q: "Lowering landing gear on soft ground without pads can:", choices: ["Be fine at highway speed", "Let the trailer sink or tip after you uncouple", "Charge the kingpin", "Improve off-tracking"], a: 1, why: "Use pads or a better surface. That is why you pause with the tractor frame under the trailer." },
  { id: "cv-65", category: "combination", topic: "Angle pull-out", q: "Pulling out from under a trailer at an angle can:", choices: ["Help the jaws release", "Bend or collapse landing gear", "Grease the fifth wheel", "Set ABS codes that are required"], a: 1, why: "Straight in, straight out." },

  { id: "pt-21", category: "pretrip", topic: "7 steps", q: "The 7-step inspection method is used so that you:", choices: ["Finish faster by skipping sides", "Do the same complete pattern every time and forget fewer items", "Only inspect after a cop stops you", "Inspect only the engine"], a: 1, why: "Approach, engine-off checks, start/in-cab, lights, walk-around, etc., in a fixed order." },
  { id: "pt-22", category: "pretrip", topic: "Key pocket", q: "During the walk-around on the skills test, the key should be:", choices: ["In the ignition with the engine running under the truck", "In your pocket so nobody can move the vehicle while you are around it", "Hidden on the tire", "Left with a stranger"], a: 1, why: "Safety for you and the examiner." },
  { id: "pt-23", category: "pretrip", topic: "Leaks approach", q: "Fresh puddles under the vehicle on approach can be:", choices: ["Always dew", "Oil, coolant, fuel, or hub oil—identify before you drive", "Required for air brakes", "A pass if they are small"], a: 1, why: "Name the fluid if you can. Fuel and hub oil leaks are serious." },
  { id: "pt-24", category: "pretrip", topic: "Power steering", q: "Power-steering hoses and pump should be checked for:", choices: ["Leaks, secure mounting, and belt condition if belt-driven", "Paint only", "ABS lamp color", "Kingpin shank"], a: 0, why: "A steering-assist failure at low speed is a heavy-truck emergency." },
  { id: "pt-25", category: "pretrip", topic: "Battery", q: "Batteries should be:", choices: ["Secure, not leaking, connections tight and not excessively corroded", "Loose so they can bounce", "Disconnected for the road test", "In the sleeper bunk"], a: 0, why: "Point to the box, lid, hold-downs, and cables." },
  { id: "pt-26", category: "pretrip", topic: "Duals", q: "Dual tires should not:", choices: ["Touch each other, have objects stuck between them, or be mismatched in size/type badly", "Have equal inflation ever", "Be inspected", "Have valve stems"], a: 0, why: "Stuck rocks between duals can start a fire. Mismatched duals carry weight poorly." },
  { id: "pt-27", category: "pretrip", topic: "Valve stems", q: "Valve stems and caps:", choices: ["Should be present and not cracked or leaking; dual stems should be accessible", "Are optional chrome", "Must be removed to drive", "Replace tread depth rules"], a: 0, why: "Missing caps let dirt in. You need to reach inner dual valves." },
  { id: "pt-28", category: "pretrip", topic: "Lug nuts", q: "Loose lug nuts may show:", choices: ["Rust streaks, shiny threads, or a gap at the nut", "Better torque", "That ABS is on", "That you should keep driving"], a: 0, why: "Look for rust trails from nuts and cracked holes in the disc." },
  { id: "pt-29", category: "pretrip", topic: "Hub oil", q: "Sight glasses or hubcaps should show:", choices: ["Proper lubricant level and no leakage", "They are empty as a goal", "Only air", "Brake fluid"], a: 0, why: "A leaking hub can destroy a bearing and drop a wheel." },
  { id: "pt-30", category: "pretrip", topic: "U-bolts", q: "U-bolts and spring hangers should be:", choices: ["Tight, present, not cracked; springs not shifted", "Missing every other one", "Used as cargo tie-downs", "Covered so you cannot see them"], a: 0, why: "Broken spring or loose U-bolt is an out-of-service item." },
  { id: "pt-31", category: "pretrip", topic: "Air bags", q: "Air-ride suspension bags should be:", choices: ["Inflated, not cut or leaking, mounted securely", "Fully deflated for highway travel always", "Filled with coolant", "Tied to the drive shaft"], a: 0, why: "A dumped bag can drop the vehicle on the tires or wreck driveline angles." },
  { id: "pt-32", category: "pretrip", topic: "Shocks", q: "Shock absorbers should be checked for:", choices: ["Secure mounts and no leaking hydraulic fluid", "Being removed for a smoother ride", "Paint color matching the cab", "ABS tone rings only"], a: 0, why: "Leaking or hanging shocks are defects." },
  { id: "pt-33", category: "pretrip", topic: "Frame", q: "Frame members should not be:", choices: ["Cracked, broken, or with loose/missing bolts at connections", "Slightly rusty ever", "Painted", "Used to mount a fifth wheel"], a: 0, why: "Frame cracks grow. Call out what would be a fail." },
  { id: "pt-34", category: "pretrip", topic: "Catwalk", q: "Catwalk, steps, and grab handles should be:", choices: ["Secure, clean enough not to be icy/slippery, and used three-points-of-contact", "Optional decoration", "Covered with grease for coupling", "Removed"], a: 0, why: "Falls off tractors are common injuries. Inspect and use them." },
  { id: "pt-35", category: "pretrip", topic: "Doors cab", q: "Cab doors should:", choices: ["Open, close, latch, and have working hinges; seals not destroyed", "Be wired open", "Be removed for airflow", "Never be checked"], a: 0, why: "A door flying open is a hazard. Also check mirrors mounted on doors." },
  { id: "pt-36", category: "pretrip", topic: "Horn test", q: "The horn(s) should:", choices: ["Work when tested in-cab", "Be disconnected", "Replace the backup alarm in all cases", "Only work at night"], a: 0, why: "City and air horns if equipped. Required communication device." },
  { id: "pt-37", category: "pretrip", topic: "Heater defroster", q: "Defroster and wipers matter because:", choices: ["You must be able to see; they are scored and they keep you legal in weather", "They charge air tanks", "They are optional in California", "They replace mirrors"], a: 0, why: "Turn them on and show they work." },
  { id: "pt-38", category: "pretrip", topic: "Neutral start", q: "Before starting the engine in the test, the transmission should be:", choices: ["In reverse", "In neutral or park as designed, with parking brake on", "In high gear", "In 1st with no brake"], a: 1, why: "The vehicle must not lurch. Parking brake on, clutch in if manual." },
  { id: "pt-39", category: "pretrip", topic: "Gauges", q: "After start-up, gauges should show:", choices: ["Oil pressure rising, volts/amps charging, coolant in range, air building, warning lamps completing bulb check", "Only the radio volume", "Zero oil pressure as normal", "ABS lamp staying on forever as a pass"], a: 0, why: "Call out each gauge and what abnormal would look like." },
  { id: "pt-40", category: "pretrip", topic: "Lighting helper", q: "To check brake lights you may:", choices: ["Ask the examiner or a helper to watch, or use a reflection, while you apply the pedal", "Assume they work", "Only check the left side", "Cover them with tape"], a: 0, why: "You cannot see your own brake lights. Have a plan." },

  { id: "dt-16", category: "doubles", topic: "More unstable", q: "A set of doubles is generally _____ a single 53-foot trailer.", choices: ["More stable than", "Less stable than, especially in emergency lane changes", "Unable to roll over compared with", "Exempt from off-tracking"], a: 1, why: "Two articulation points and a light rear trailer increase whip and rollover risk." },
  { id: "dt-17", category: "doubles", topic: "Speed doubles", q: "With doubles you should:", choices: ["Take ramps faster because the rear is light", "Go even slower in curves and on ramps than with a single trailer", "Rely on crack-the-whip to straighten the load", "Never use mirrors"], a: 1, why: "Rearward amplification makes a moderate steer into a big rear swing." },
  { id: "dt-18", category: "doubles", topic: "Connect dolly air", q: "When coupling doubles, air and electric must:", choices: ["Reach both trailers, with shut-offs set correctly", "Only reach the first trailer", "Be left on dummy couplers while driving", "Be crossed on purpose"], a: 0, why: "Walk the whole combination. Test that the last trailer has lights and brakes." },
  { id: "dt-19", category: "doubles", topic: "Safety chains", q: "Some pintle hookups also use safety chains or cables. They should be:", choices: ["Crossed or attached as designed so they can catch the dolly if the pintle fails", "Left dragging", "Tied to a brake hose", "Removed because they rattle"], a: 0, why: "A dropped dolly is a catastrophe. Inspect chains, hooks, and latches." },
  { id: "dt-20", category: "doubles", topic: "Empty rear", q: "A very light rear trailer in a double set:", choices: ["Improves stability", "Is more likely to whip or turn over; that is why the heavy trailer belongs in front", "Cannot have ABS", "Should always be first"], a: 1, why: "Heavy first, light last." },

  { id: "tk-16", category: "tanker", topic: "Partial load", q: "A partially loaded smooth-bore tank can be:", choices: ["The most stable tanker condition", "Worse for surge than a full or well-compartmented load", "Illegal always", "Unaffected by braking"], a: 1, why: "Liquid has room to run. Smooth tanks do not slow it much." },
  { id: "tk-17", category: "tanker", topic: "Curves tanker", q: "Posted curve speeds for cars on a tanker are:", choices: ["Usually too fast; slow more", "Always correct", "Too slow", "Only for doubles"], a: 0, why: "High CG plus surge. Slow before the curve, do not brake in the middle of it." },
  { id: "tk-18", category: "tanker", topic: "Manhole", q: "Manhole covers and valves after loading should be:", choices: ["Closed, latched, and not leaking", "Left open for outage", "Wired open", "Covered with a rag only"], a: 0, why: "Product on the catwalk is a slip and environmental spill." },
  { id: "tk-19", category: "tanker", topic: "Baffle damage", q: "If baffles are damaged, surge can:", choices: ["Improve", "Get worse because the tank behaves more like a smooth bore", "Disappear", "Only affect ABS"], a: 1, why: "Do not assume a baffled tank is still baffled after a wreck or corrosion." },
  { id: "tk-20", category: "tanker", topic: "Grade tanker", q: "On a long downgrade in a tanker you should:", choices: ["Use a low gear even more carefully because surge can shove you faster after you brake", "Coast in neutral", "Use only the hand valve", "Fill the tank at the top of the hill"], a: 0, why: "When you release brakes, liquid can push you. Engine braking and smooth applies matter more." },

  { id: "hz-16", category: "hazmat", topic: "9 classes", q: "Class 3 HazMat is:", choices: ["Explosives", "Gases", "Flammable liquids", "Radioactive"], a: 2, why: "Memorize the nine classes. Diesel and gasoline as cargo are Class 3 when regulated." },
  { id: "hz-17", category: "hazmat", topic: "Shipper vs carrier", q: "The carrier/driver is responsible for:", choices: ["Nothing if the shipper signed the certification", "Refusing improper loads, checking papers and placards, and safe transport", "Only fueling", "Rewriting the chemical formula"], a: 1, why: "You cannot hide behind a signature if packages are leaking in front of you." },
  { id: "hz-18", category: "hazmat", topic: "Parking", q: "Placarded loads have extra rules about:", choices: ["Parking near open flame, tunnels, and sometimes on the highway; know Section 9", "Parking anywhere a car can park, always", "Leaving the truck running in a tunnel for AC", "Hiding placards at night"], a: 0, why: "Do not park a placarded vehicle where the handbook forbids it." },
  { id: "hz-19", category: "hazmat", topic: "Fires HazMat", q: "With a HazMat fire or leak, a driver should:", choices: ["Taste the product", "Keep shipping papers available for responders and not try heroic transfers unless trained", "Hose it into a creek", "Leave papers in the burning cab if that is where they are and walk away without telling anyone"], a: 1, why: "Your job is isolation, notification, and information. The ERG and papers save firefighters." },
  { id: "hz-20", category: "hazmat", topic: "X endorsement", q: "An X endorsement on a CDL means the driver passed:", choices: ["Only passenger", "Both tank vehicle and HazMat knowledge tests", "Only doubles", "Only air brakes"], a: 1, why: "X = N + H, used for placarded tank HazMat." },

  { id: "ps-13", category: "passenger", topic: "Railroad bus", q: "When a bus must stop at a railroad crossing, the driver should:", choices: ["Open the door or window, look and listen, and not proceed until it is safe", "Rely only on the GPS", "Stop on the tracks if the light is yellow", "Shift while crossing to save the clutch"], a: 0, why: "Quiet the bus, look, listen, then cross in a gear that will not require shifting." },
  { id: "ps-14", category: "passenger", topic: "Charter", q: "On a charter trip, passenger comfort stops should be planned so:", choices: ["Riders are not stranded and the bus is legally parked", "You leave people at random exits", "You never inspect the bus", "Standees block the stepwell"], a: 0, why: "You are responsible for the group. Park legally and count heads." },
  { id: "ps-15", category: "passenger", topic: "Prohibited carry", q: "Buses typically must not carry:", choices: ["Riders’ ordinary luggage in a proper baggage area", "Explosives, labeled HazMat, or other prohibited articles listed in the handbook", "A fire extinguisher", "Warning triangles"], a: 1, why: "Section 4 lists forbidden cargo. You are not a HazMat truck with seats." }
];
